package platform

import "runtime"

func isSupportedNative(goos string) bool {
	switch goos {
	case "linux", "darwin", "freebsd", "openbsd", "netbsd", "solaris", "aix", "dragonfly":
		return true
	default:
		return false
	}
}

var CurrentGOOS = runtime.GOOS

package platform

// NativeCapability reflects the capability of the currently running
// platform: "native" when the OS is natively supported, otherwise it
// falls back to "stub".
var NativeCapability = func() string {
	if isSupportedNative(CurrentGOOS) {
		return "native"
	}
	return "stub"
}()

func Capability() string { return NativeCapability }
